function acquireProfileWriteLease(){
  const now=Date.now();
  try{
    const old=readWriterLease();
    if(old?.tabId&&old.tabId!==TAB_INSTANCE_ID&&Number(old.expiresAt)>now)return false;
    localStorage.setItem(PROFILE_WRITER_LEASE_KEY,JSON.stringify({tabId:TAB_INSTANCE_ID,expiresAt:now+WRITER_LEASE_MS}));
    return readWriterLease()?.tabId===TAB_INSTANCE_ID;
  }catch(e){console.warn('Writer lease unavailable',e);return true}
}

function allRecentMockDetails(limit=6){
  const rows=[];
  (profile.mockHistory||[]).slice(0,limit).forEach(h=>{
    (h.details||[]).forEach(d=>rows.push({...d,examDate:h.date,mode:h.mode}));
  });
  return rows;
}

function beginMigrationJournal(raw,checksum,fromSchema){
  try{localStorage.setItem(PROFILE_MIGRATION_JOURNAL_KEY,JSON.stringify({format:'fequest-migration-v1',fromSchema,toSchema:PROFILE_SCHEMA_VERSION,startedAt:new Date().toISOString(),raw,checksum:checksum||null}))}catch(_e){}
}

function bestCurrentRawForRollback(){
  try{const a=currentAtomicProfile();if(a)return {raw:JSON.stringify(a.profile),checksum:profileIntegrityChecksum(a.profile)}}catch(_e){}
  const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;
  try{const c=validRawWithChecksum(raw,localStorage.getItem(PROFILE_CHECKSUM_KEY)||null);return {raw,checksum:c.sourceChecksum}}catch(_e){return null}
}

function buildReviewItem(q){
  if(profile.settings.variantReview===false)return q;
  return generateVariant(q)||siblingVariant(q)||q;
}

function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

function buildTodayTasks(){
  const daysNow=examDaysRemaining();
  const totalNow=effectiveStudyMinutes();
  if(daysNow!=null&&daysNow>=0&&daysNow<=7)return buildTaperTodayTasks(daysNow,totalNow);
  const alloc=taskAllocation(totalNow);
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;
  const lesson=nextLessonChoice();
  const b=nextBChoice(alloc.subjectB);
  const bMinutes=(b.mode==='compound'||b.mode==='securityMock')?Math.min(20,alloc.subjectB):alloc.subjectB;
  const lessonMinutes=alloc.lesson+Math.max(0,alloc.subjectB-bMinutes);
  const weak=weakestSkill();
  const days=examDaysRemaining();
  const finalPhase=days!=null&&days<=14;

  const rxReady=window.FEQUEST_RX_READY===true;
  const rx=rxReady?recommendedPrescription():{kind:'knowledge',cat:lesson.skill,reason:'データ不足'};
  const rxMeta=rxReady?prescriptionMeta(rx):{icon:'📘',title:lesson.title,desc:'未完了教材を優先'};
  const useRx=rxReady && rx.kind!=='knowledge';

  let learnTask;
  if(lesson.complete){
    const focus=shortFinalFocusRecommendation();
    learnTask={
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:lessonMinutes,focus
    };
  }else if(useRx){
    learnTask={
      type:'prescription',icon:rxMeta.icon,bg:'blue',
      title:rxMeta.title,desc:`原因「${rx.reason}」に合わせて自動処方`,
      minutes:lessonMinutes,rx
    };
  }else{
    learnTask={
      type:'lesson',icon:'📘',bg:'blue',
      title:lesson.title,desc:`${lesson.skill}・未完了教材を優先`,
      minutes:lessonMinutes,lessonId:lesson.id
    };
  }

  return [
    {
      type:'review',icon:'🧠',bg:'green',
      title:'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`復習期限の問題 ${due}問を優先`:`今日の復習期限はなし。「${weak}」を補強`,
      minutes:alloc.review
    },
    learnTask,
    {
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`プログラムトレース：${b.title}`:b.mode==='security'?`セキュリティ：${b.title}`:b.mode==='compound'?`複合演習：${b.title}`:b.mode==='securityMock'?b.title:`実戦：${b.title}`,
      desc:b.mode==='trace'?'科目B アルゴリズム':b.mode==='security'?'科目B 情報セキュリティ':b.mode==='compound'?'科目B アルゴリズム・20分実戦':b.mode==='securityMock'?'科目B セキュリティ・20分実戦':'科目B 実戦',
      minutes:bMinutes,bmode:b.mode,bid:b.id
    },
    {
      type:'boss',icon:'👑',bg:'yellow',
      title:finalPhase?'直前総合チェック':'今日の総合チェック',
      desc:finalPhase?'判断3問＋適用2問・分野を散らして5問':'全分野から5問・仕上げチェック',
      minutes:alloc.boss
    }
  ];
}

function clearBFinalResume(){
  try{localStorage.removeItem(BFINAL_RESUME_KEY)}catch(e){}
}

function courseAContinueId(){
  const ui=readUiState();
  if(ui.lessonId&&CORE_A_IDS.includes(ui.lessonId)&&(profile.lessonProgress?.[ui.lessonId]||0)<100)return ui.lessonId;
  return nextLessonChoice()?.id||null;
}

function currentAtomicProfile(){
  const raw=localStorage.getItem(PROFILE_ATOMIC_KEY);
  if(!raw)return null;
  return decodeAtomicProfileEnvelope(raw);
}

function ensureTodayPlanSnapshot(force=false){
  const rec=getDailyRecord();
  const stale=rec.planVersion!=='v98';
  if(force||!Array.isArray(rec.tasks)||!rec.tasks.length||stale){
    const old=snapshotDailyTasks(Array.isArray(rec.tasks)?rec.tasks:[]);
    const fresh=snapshotDailyTasks(buildTodayTasks());
    const done=rec.done||{};
    rec.tasks=fresh.map(t=>{
      const slot=dailyTaskSlot(t);
      if(done[slot])return old.find(x=>dailyTaskSlot(x)===slot)||t;
      return t;
    });
    rec.targetMinutes=rec.tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0);
    rec.planVersion='v98';
    rec.plannedAt=rec.plannedAt||new Date().toISOString();
    if(stale)rec.replannedAt=new Date().toISOString();
    persistProfileSilently();
  }
  return rec.tasks;
}

async function ensureVersionRecoveryCheckpoint(){
  try{
    if(localStorage.getItem(PROFILE_VERSION_CHECKPOINT_KEY)===APP_VERSION)return false;
    if(profileWriteBlocked||profileConflictBlocked)return false;
    const ok=await writeRecoveryCheckpoint(profile,`version-${APP_VERSION}`,true);
    if(ok){localStorage.setItem(PROFILE_VERSION_CHECKPOINT_KEY,APP_VERSION);refreshPwaHealth();return true;}
  }catch(e){console.warn('Version recovery checkpoint failed',e)}
  return false;
}

function examDaysRemaining(){
  const val=profile.settings?.examDate;if(!val)return null;
  const target=new Date(val+'T12:00:00'),now=new Date();now.setHours(12,0,0,0);
  return Math.ceil((target-now)/86400000);
}

function examPaceStatus(){
  const days=examDaysRemaining(),baseline=Number(profile.settings?.studyMinutes)||60,remaining=estimateRemainingStudyMinutes(),recent=recentCalendarPace(),phase=examStudyPhase(days);
  if(days==null)return {hasExam:false,baseline,effective:baseline,remaining,recent,phase};
  if(days<0)return {hasExam:true,expired:true,days,baseline,effective:baseline,remaining,recent,phase};
  const available=Math.max(1,days),required=remaining/available,currentPace=recent.enough?recent.avg:baseline,paceSource=recent.enough?'recent':'plan';
  const projectedDays=currentPace>0?Math.ceil(remaining/currentPace):9999,projectedDate=new Date();projectedDate.setHours(12,0,0,0);projectedDate.setDate(projectedDate.getDate()+projectedDays);
  const slack=available-projectedDays;
  let status='danger';
  if(required<=0||currentPace>=required*1.20)status='good';else if(currentPace>=required*.95)status='ok';else if(currentPace>=required*.75)status='warn';
  const auto=profile.settings?.autoPace!==false,suggested=Math.max(baseline,roundUp5(required*1.10));
  const cap=taperStudyCap(days);
  const taper=cap!=null;
  const normalEffective=auto?Math.min(120,suggested):baseline;
  // 残り7日以内は「残学習量を全部消化する」ための追い込みを止める。
  // 標準時間が短い利用者は増やさず、長い利用者だけ段階的に上限を下げる。
  const effective=taper?Math.min(baseline,cap):normalEffective;
  const adjustedDays=effective>0?Math.ceil(remaining/effective):9999,maxDate=new Date();maxDate.setHours(12,0,0,0);maxDate.setDate(maxDate.getDate()+Math.ceil(remaining/120));
  return {hasExam:true,expired:false,days,baseline,remaining,recent,phase,required,currentPace,paceSource,projectedDays,projectedDate,slack,status,auto,effective,canRecover:adjustedDays<=available,maxDate,taper,taperCap:cap};
}

function exportLearningData(){
  if(profileRecoverySource==='future'){
    showAppNotice('error','最新版へ更新してから書き出してください','この画面より新しい形式の学習データが保存されています。古い画面の空状態を誤ってバックアップしないよう、書き出しを停止しました。','更新を確認',()=>checkForAppUpdate(true));
    return false;
  }
  const payload=makeBackupPayload(profile);
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`fe-quest-backup-${localDateISO(0)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
  try{localStorage.setItem(PROFILE_LAST_EXPORT_KEY,new Date().toISOString())}catch(_e){}
  popToast('整合性チェック付きで学習データを書き出しました');refreshPwaHealth?.();
}

function exportPreservedCorruptProfile(){
  const raw=localStorage.getItem(CORRUPT_PROFILE_KEY);if(!raw){popToast('保全されている破損データはありません');return false}
  downloadTextFile(`fe-quest-preserved-corrupt-${localDateISO(0)}.txt`,raw,'text/plain');popToast('破損時の元データをそのまま保全しました');return true;
}

async function exportRecoveryDiagnostics(){
  const quick=quickProfileIntegrityState();let points=[];try{points=await recoveryCandidates()}catch(_e){}
  let storage=null;try{if(navigator.storage?.estimate){const x=await navigator.storage.estimate();storage={usage:x.usage||0,quota:x.quota||0}}}catch(_e){}
  let persisted=null;try{if(navigator.storage?.persisted)persisted=await navigator.storage.persisted()}catch(_e){}
  const a=(()=>{try{return currentAtomicProfile()}catch(_e){return null}})();
  const report={
    format:'fequest-diagnostics-v1',createdAt:new Date().toISOString(),appVersion:APP_VERSION,profileSchemaVersion:profile.profileSchemaVersion,
    profile:{revision:a?.revision??profileBaseRevision,integrity:quick.label,writeBlocked:profileWriteBlocked,conflictBlocked:profileConflictBlocked,recoverySource:profileRecoverySource||null,lastSaveFailure:lastProfileSaveFailure||null,lastSaveFailureAt:lastProfileSaveFailureAt?new Date(lastProfileSaveFailureAt).toISOString():null,summary:recoveryProfileMetrics(profile)},
    recovery:{usable:points.filter(x=>x.valid).length,invalid:points.filter(x=>!x.valid).length,preImportRollback:!!localStorage.getItem(PRE_IMPORT_PROFILE_KEY),preManualRollback:!!localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY),corruptRawPreserved:!!localStorage.getItem(CORRUPT_PROFILE_KEY)},
    environment:{standalone:isStandalone(),online:navigator.onLine,serviceWorkerControlled:!!navigator.serviceWorker?.controller,persistentStorage:persisted,storage}
  };
  downloadTextFile(`fe-quest-diagnostics-${localDateISO(0)}.json`,JSON.stringify(report,null,2));popToast('診断レポートを書き出しました');
}

function feqLearningRuntimeChecks(){
    return [
      currentCheck('cognitive-review-policy','Cognitive demand must influence review and weakness drills',()=>
        typeof cognitiveWeight==='function'&&cognitiveWeight({cognitiveLevel:'想起'})===0.8&&cognitiveWeight({cognitiveLevel:'適用'})===1&&cognitiveWeight({cognitiveLevel:'判断'})===1.25&&
        typeof categoryCognitiveEvidence==='function'&&typeof subjectACognitiveEvidence==='function'&&
        String(reviewUrgency).includes('cognitiveRisk')&&String(coreTopicLearningState).includes('advancedReady')&&String(startQuiz).includes('cogcat:'),5),
      currentCheck('mastery-integrity','Mastery must require retention, higher-order evidence and chapter integration',()=>
        typeof ensureChapterMasteryProfile==='function'&&typeof chapterIntegrationEvidence==='function'&&
        String(coreTopicLearningState).includes('minRetention>=85')&&String(coreTopicLearningState).includes('advancedMasterReady')&&String(coreTopicLearningState).includes('chapterReady')&&
        typeof courseMasteryStatus==='function'&&typeof finalFocusRecommendation==='function'&&
        String(courseMasteryStatus).includes("name:'科目Aフル模試'")&&String(courseMasteryStatus).includes("name:'科目B総合実戦'")&&
        String(chooseFinalBossQuestions).includes("'判断'")&&String(chooseFinalBossQuestions).includes("'適用'"),7),
      currentCheck('taper-policy','Exam taper policy and light-review routing must remain active',()=>
        typeof taperStudyCap==='function'&&taperStudyCap(7)===45&&taperStudyCap(3)===30&&taperStudyCap(1)===15&&taperStudyCap(0)===10&&
        examStudyPhase(3).allowNew===false&&examStudyPhase(3).allowLongExam===false&&examStudyPhase(0).id==='examDay'&&
        typeof chooseExamWarmupQuestions==='function'&&typeof chooseTaperReviewQuestions==='function'&&
        String(buildTodayTasks).includes('buildTaperTodayTasks')&&String(finalFocusRecommendation).includes('deepTaper')&&String(finalFocusRecommendation).includes("kind:'warmup'"),5),
      currentCheck('curriculum-runtime','Curriculum, lesson guides and pace engines must remain complete',()=>{
        const lessonIds=Object.keys(LESSONS||{});
        return lessonIds.length>=30&&typeof examPaceStatus==='function'&&typeof effectiveStudyMinutes==='function'&&typeof estimateRemainingStudyMinutes==='function'&&
          LAB_LESSON_IDS.every(id=>LESSON_GUIDES[id]&&LESSON_GUIDES[id].points?.length>=3)&&
          CORE_A_IDS.length===130&&Object.keys(CORE_A_CONTENT_ENRICHMENT).length===130&&CORE_A_IDS.every(id=>LESSONS[id]?.pages?.every(p=>!p.quiz&&!p.interactive));
      },7),
      currentCheck('syllabus-coverage','Current FE syllabus mapping must remain Ver.9.2 with 96 mapped small categories',()=>
        FE_SYLLABUS_VERSION==='9.2'&&FE_SYLLABUS_V92_COVERAGE.length===96&&FE_SYLLABUS_V92_COVERAGE.every(x=>x.topicIds.length&&x.topicIds.every(id=>CORE_A_IDS.includes(id))),3),
      currentCheck('mock-blueprints','Subject A full/half mock blueprints must preserve count, difficulty and cognition',()=>
        typeof MOCK_BLUEPRINTS!=='undefined'&&
        MOCK_BLUEPRINTS.full.count===60&&MOCK_BLUEPRINTS.full.basic===15&&MOCK_BLUEPRINTS.full.standard===30&&MOCK_BLUEPRINTS.full.practical===15&&
        MOCK_BLUEPRINTS.half.count===30&&MOCK_BLUEPRINTS.half.basic===8&&MOCK_BLUEPRINTS.half.standard===14&&MOCK_BLUEPRINTS.half.practical===8&&
        JSON.stringify(MOCK_BLUEPRINTS.full.cognitive)===JSON.stringify({'想起':15,'適用':29,'判断':16})&&
        JSON.stringify(MOCK_BLUEPRINTS.half.cognitive)===JSON.stringify({'想起':8,'適用':13,'判断':9}),4),
      currentCheck('subject-b-exercises','Subject B exercise, mini-mock, semantic and compound-set contracts must remain valid',()=>
        Array.isArray(B_EXERCISES)&&B_EXERCISES.length===20&&typeof B_MOCK_COUNT!=='undefined'&&B_MOCK_COUNT===8&&
        Object.values(B_MOCK_QUOTAS).reduce((a,b)=>a+b,0)===8&&B_EXERCISES.every(ex=>ex.steps.filter(s=>s.predict).length===2)&&
        typeof validateSubjectBSemantics==='function'&&validateSubjectBSemantics().ok&&Array.isArray(B_COMPOUND_SETS)&&B_COMPOUND_SETS.length===15,6),
      currentCheck('subject-b-security-final','Subject B compound/security/final blueprints and final-resume guard must remain valid',()=>
        B_COMPOUND_SETS.every(s=>s.qs?.length===3)&&B_COMPOUND_SETS.flatMap(s=>s.qs).every(q=>q.kind&&q.qlevel&&q.point&&q.pitfall)&&
        Array.isArray(SECURITY_SCENARIOS)&&SECURITY_SCENARIOS.length===15&&typeof SECURITY_MOCK_COUNT!=='undefined'&&SECURITY_MOCK_COUNT===8&&
        Object.values(SECURITY_MOCK_QUOTAS).reduce((a,b)=>a+b,0)===8&&typeof B_FINAL_COUNT!=='undefined'&&B_FINAL_COUNT===20&&B_FINAL_ALGO_COUNT===16&&B_FINAL_SEC_COUNT===4&&
        typeof restoreBFinalResume==='function'&&typeof saveBFinalResume==='function'&&typeof renderBFinalReadiness==='function'&&String(startBFinal).includes('days<=3'),7),
      currentCheck('profile-backup-roundtrip','Profile backup engine must round-trip current schema and checksum',()=>{
        if(profile.profileSchemaVersion!==PROFILE_SCHEMA_VERSION||typeof normalizeProfileData!=='function'||typeof makeBackupPayload!=='function'||typeof decodeBackupPayload!=='function') return false;
        const backup=makeBackupPayload(profile),decoded=decodeBackupPayload(backup);
        return decoded.profile.profileSchemaVersion===PROFILE_SCHEMA_VERSION&&profileIntegrityChecksum(decoded.profile)===backup.checksum;
      },4),
      currentCheck('profile-schema-migration','Profile migration must preserve v3 progress and reject future schemas',()=>{
        const migrated=normalizeProfileData({profileSchemaVersion:3,xp:7,lessonProgress:{probe:100},skills:{...DEFAULT_PROFILE.skills}});
        let rejected=false;try{normalizeProfileData({profileSchemaVersion:PROFILE_SCHEMA_VERSION+1,xp:1});}catch(e){rejected=e?.code==='FUTURE_PROFILE_SCHEMA';}
        return migrated.profileSchemaVersion===5&&migrated.xp===7&&migrated.lessonProgress.probe===100&&rejected;
      },2),
      currentCheck('daily-resilience','Daily plan, readiness and reload-resilience engines must exist',()=>
        typeof ensureTodayPlanSnapshot==='function'&&typeof rebuildTodayPlanPreservingDone==='function'&&typeof readinessComponents==='function'&&
        typeof restoreResilientUiState==='function'&&typeof persistResilientUiState==='function',3),
      currentCheck('recovery-safety','Recovery diagnostics, rollback protection and mastery recovery routing must remain available',()=>
        typeof runStorageSelfTest==='function'&&typeof exportRecoveryDiagnostics==='function'&&typeof exportPreservedCorruptProfile==='function'&&
        !!PRE_MANUAL_RESTORE_PROFILE_KEY&&String(restoreRecoveryCandidate).includes('PRE_MANUAL_RESTORE_PROFILE_KEY')&&String(restoreRecoveryCandidate).includes('pre-manual-restore')&&
        typeof syncMasteryRecoveryHistory==='function'&&typeof masteryRecoveryInfo==='function'&&String(nextMasterTopicCandidate).includes('masteryRecoveryInfo')&&
        SAFE_RESUME_SCREENS.has('map')&&SAFE_RESUME_SCREENS.has('problems'),4),
      currentCheck('roadmap-shape','Roadmap must keep five integrated stages covering all Core A chapters',()=>{
        const roadmap=roadmapData();
        return roadmap.length===5&&roadmap[0].desc.includes('第1〜13章')&&roadmap[1].desc.includes('第14〜21章');
      },2),
      currentCheck('peer-distractor-metadata','Applied linked questions and comparison challenges must retain neighboring-topic metadata',()=>
        CORE_A_LINKED_QUESTIONS.filter(q=>['application','discrimination'].includes(q.angle)).every(q=>Array.isArray(q.distractorTopicIds)&&q.distractorTopicIds.length===3)&&
        CORE_A_CHALLENGE_QUESTIONS.filter(q=>q.angle==='comparison').every(q=>Array.isArray(q.comparisonTopicIds)&&q.comparisonTopicIds.length===2),2),
      currentCheck('variant-generator','Generated-variant validation must produce at least one valid variant',()=>typeof validateGeneratedVariants!=='function'||validateGeneratedVariants()>0,1)
    ];
  }

function finalFocusRecommendation(status=courseMasteryStatus()){
  const days=examDaysRemaining();
  const urgentPhase=days!=null&&days>=0&&days<=14;
  const deepTaper=days!=null&&days>=0&&days<=3;
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;

  if(days===0){
    return {kind:'warmup',icon:'☀️',title:'今日は3問だけ確認',desc:'新規教材も長時間模試も追加しません。既習3問で感覚だけ整えます。',button:'ウォームアップ3問'};
  }
  if(days===1){
    if(routes||due)return {kind:'review',icon:'🧠',title:'前日は復習だけ',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。長時間模試や新規教材は追加しません。`,button:'5問まで確認'};
    return {kind:'warmup',icon:'🌙',title:'前日は軽い確認だけ',desc:'既習3問だけ確認し、新しい範囲は増やしません。',button:'ウォームアップ3問'};
  }

  if((routes||due)&&((urgentPhase)||(status.mem.due>10))){
    return {kind:'review',icon:'🧠',title:'最優先：復習待ちを解消',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。判断問題を優先して戻します。`,button:deepTaper?'5問まで確認':'復習を始める'};
  }

  // 残り3日以内は、未完了教材があっても新規範囲を広げない。
  if(!deepTaper&&status.lessonDone<130){
    const lesson=nextLessonChoice();
    return {kind:'lesson',icon:'📘',title:'未完了教材を埋める',desc:`残り ${130-status.lessonDone}テーマ。弱い分野から未完了教材を進めます。`,button:'次の教材へ',lessonId:lesson.id};
  }

  if(status.bTraining<90&&!urgentPhase){
    const b=nextBChoice(20);
    return {kind:'subjectB',icon:'💻',title:'科目Bの基礎演習を完成',desc:`科目B学習 ${status.bTraining}% 。未完了のアルゴリズム/セキュリティを優先します。`,button:'科目Bを続ける',b};
  }

  if(deepTaper){
    const weakEvidence=categoryCognitiveEvidence(status.weakest[0]);
    if(Number(status.weakest[1])<70){
      const level=weakEvidence.weakest.level;
      return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${level}を短く補強`,desc:'残り3日以内は新規教材やフル模試ではなく、既習の最弱思考を10問だけ確認します。',button:`${level}を10問`,cat:status.weakest[0],level};
    }
    if(status.bTraining<90){
      const b=nextBChoice(10);
      return {kind:'subjectB',icon:'💻',title:'科目Bを1セットだけ確認',desc:'100分総合実戦は追加せず、既存の短い演習を一つ確認します。',button:'科目Bを確認',b};
    }
    const chapter=nextReadyUnpassedChapter();
    if(chapter){
      return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を短く統合確認`,desc:'学習済みの章だけを確認します。未学習範囲は混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
    }
    const x=nextMasterTopicCandidate();
    if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
      return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:'既習テーマの保持を整えます。新しい知識は増やしません。',button:'テーマ演習',topicId:x.topic.id};
    }
    return {kind:'warmup',icon:'✅',title:'既習3問だけ確認',desc:'ここからは仕上がりを崩さないことを優先します。',button:'ウォームアップ3問'};
  }

  if(urgentPhase&&!status.aMock.passed){
    return {kind:'aMock',icon:'🏁',title:'科目Aを本番時間で確認',desc:'フル模試2回の安定条件が未達です。90分を確保できる日に本番型で確認します。',button:'フル模試90分を始める',long:true};
  }

  if(urgentPhase&&!status.bFinal.passed){
    return {kind:'bFinal',icon:'💻',title:'科目B総合実戦で確認',desc:'直近2回の安定条件が未達です。100分を確保してアルゴリズム＋セキュリティを通しで確認します。',button:'科目B総合100分を始める',long:true};
  }

  const weakEvidence=categoryCognitiveEvidence(status.weakest[0]);
  if(Number(status.weakest[1])<70){
    const level=weakEvidence.weakest.level;
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${level}を補強`,desc:`最低分野 ${Math.round(status.weakest[1])}% 。最も弱い思考段階「${level}」を10問で直接補強します。`,button:`${level}を10問`,cat:status.weakest[0],level};
  }

  if(status.chapterPassed<21){
    const row=nextUnpassedChapter();
    return {kind:'chapter',icon:'🧩',title:`第${row?.ch||1}章の統合確認`,desc:`章末統合 ${status.chapterPassed}/21。80%以上到達＋直近70%以上維持を習得判定の統合証拠にします。`,button:`第${row?.ch||1}章を12問で確認`,chapter:row?.ch||1};
  }

  if(status.bTraining<90){
    const b=nextBChoice(20);
    return {kind:'subjectB',icon:'💻',title:'科目Bの基礎演習を完成',desc:`科目B学習 ${status.bTraining}% 。未完了演習を優先します。`,button:'科目Bを続ける',b};
  }

  if(!status.aMock.passed){
    return {kind:'aMock',icon:'🏁',title:'科目Aフル模試を安定させる',desc:'直近2回で平均75%以上・各70%以上をFE QUESTの総仕上げ基準にしています。',button:'フル模試90分を始める',long:true};
  }
  if(!status.bFinal.passed){
    return {kind:'bFinal',icon:'💻',title:'科目B総合実戦を安定させる',desc:'直近2回で平均70%以上・各65%以上をFE QUESTの総仕上げ基準にしています。',button:'科目B総合100分を始める',long:true};
  }

  if(status.stable<117||status.master<130){
    const x=nextMasterTopicCandidate();
    if(x){
      if(x.state.key==='stable'&&!x.state.chapterReady){
        return {kind:'chapter',icon:'🧩',title:`第${x.topic.chapter}章の章末確認`,desc:`「${x.topic.title}」はテーマ内では習得水準ですが、章横断の確認が残っています。`,button:`第${x.topic.chapter}章を確認`,chapter:x.topic.chapter};
      }
      return masteryRecoveryInfo(x.topic.id)?{kind:'topic',icon:'↩️',title:`${x.topic.title}の習得状態を戻す`,desc:`${masteryRecoveryReason(x.state)} 現在「${x.state.label}」。`,button:'必要な復習を始める',topicId:x.topic.id}:{kind:'topic',icon:'⭐',title:`${x.topic.title}を習得状態へ`,desc:`現在「${x.state.label}」。保持と高次問題の証拠を整えます。`,button:'テーマ演習を始める',topicId:x.topic.id};
    }
  }

  if(!status.gates.find(g=>g.id==='memory')?.passed){
    return {kind:'review',icon:'🧠',title:'記憶を最終メンテナンス',desc:`推定保持 ${status.mem.avg}%・要復習 ${status.mem.due}問。新規学習より保持の回復を優先します。`,button:'復習を始める'};
  }

  const ev=categoryCognitiveEvidence(status.weakest[0]);
  return {kind:'cognitive',icon:'✅',title:'総仕上げ維持',desc:`主要ゲートを満たしています。最も弱い「${status.weakest[0]}・${ev.weakest.level}」を短く維持します。`,button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}

async function getRecoveryCandidate(kind,id){
  if(kind==='last-good'){
    const raw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);if(!raw)throw new Error('一世代前のデータがありません');
    return validRawWithChecksum(raw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null).profile;
  }
  const rows=await recoverySnapshots();
  const row=rows.find(x=>String(x.id)===String(id));if(!row)throw new Error('復旧点が見つかりません');
  return decodeBackupPayload(row.payload).profile;
}

async function importLearningDataFile(file){
  try{
    if(file?.size>5*1024*1024)throw new Error('バックアップファイルが大きすぎます');
    const parsed=JSON.parse(await file.text());
    const decoded=decodeBackupPayload(parsed);
    const message=`現在の学習データを、次のバックアップで置き換えますか？\n\n${backupSummary(decoded)}\n\n現在のデータは端末内に一時退避され、あとから1回だけ戻せます。`;
    if(!confirm(message))return;

    const current=localStorage.getItem(STORAGE_KEY)||JSON.stringify(normalizeProfileData(profile));
    localStorage.setItem(PRE_IMPORT_PROFILE_KEY,current);
    if(!profileWriteBlocked)queueRecoveryCheckpoint('pre-import',true);

    profileWriteBlocked=false;
    profileRecoveryNeedsIndexedDb=false;
    profile=stampProfileForSave(decoded.profile);
    const importedResult=writeCurrentProfile(profile,{preservePrevious:true,skipConflictCheck:true});
    profile=importedResult.profile;rememberCommittedProfile(profile);
    profileConflictBlocked=false;profileConflictNoticeShown=false;
    queueRecoveryCheckpoint('import',true);
    localStorage.removeItem('fequest_bfinal_resume_v1');
    localStorage.removeItem('fequest_ui_state_v2');

    popToast('学習データを読み込みました');setTimeout(()=>location.reload(),500);
  }catch(e){
    console.warn('Import failed',e);
    showAppNotice('error','学習データを読み込めませんでした',e?.message||'FE QUESTのバックアップファイルか確認してください。');
  }
}

function launchFinalFocus(f=finalFocusRecommendation()){
  if(!f)return;
  if(f.kind==='warmup'){showScreen('problems');startQuiz('warmup');return;}
  if(f.kind==='review'){
    const days=examDaysRemaining();
    if(days!=null&&days>=0&&days<=3){showScreen('problems');startQuiz('taperreview');return;}
    const j=actionableReviewJourneys()[0];
    if(j)startJourneyAction(j.id);
    else{showScreen('problems');startQuiz('review');}
    return;
  }
  if(f.kind==='lesson'){startLesson(f.lessonId);return;}
  if(f.kind==='chapter'){showScreen('problems');startQuiz(`corechapter:${f.chapter}`);return;}
  if(f.kind==='topic'){showScreen('problems');startQuiz(`coretopic:${f.topicId}`);return;}
  if(f.kind==='cognitive'){showScreen('problems');startQuiz(`cogcat:${f.cat}:${f.level}`);return;}
  if(f.kind==='subjectB'){
    showScreen('trace');
    const b=f.b||nextBChoice(20);
    if(b.mode==='trace'){setBMode('trace');if(b.id)startBExercise(b.id);}
    else if(b.mode==='security'){setBMode('security');if(b.id)startSecurityScenario(b.id);}
    else if(b.mode==='compound'){setBMode('mock');startCompoundChallenge();}
    else if(b.mode==='securityMock'){setBMode('security');startSecurityMock();}
    return;
  }
  if(f.kind==='aMock'){showScreen('mock');startMock('full');return;}
  if(f.kind==='bFinal'){showScreen('trace');setBMode('final');startBFinal();return;}
}

function loadProfile(){
  recoverInterruptedMigrationIfNeeded();

  const atomicRaw=localStorage.getItem(PROFILE_ATOMIC_KEY);
  if(atomicRaw){
    try{
      const a=decodeAtomicProfileEnvelope(atomicRaw);
      profileBaseRevision=a.revision;
      repairCompatibilityMirror(a.profile);
      return a.profile;
    }catch(e){
      console.warn('Atomic profile could not be used; checking compatibility mirror',e);
      if(e?.code==='FUTURE_PROFILE_SCHEMA'){
        profileRecoveryWarning=true;profileRecoveryReason=e?.message||String(e);profileRecoverySource='future';profileWriteBlocked=true;
        return structuredClone(DEFAULT_PROFILE);
      }
      try{localStorage.setItem(CORRUPT_PROFILE_KEY,atomicRaw)}catch(_e){}
    }
  }

  let raw=localStorage.getItem(STORAGE_KEY);
  if(!raw){
    for(const key of LEGACY_STORAGE_KEYS){
      const legacy=localStorage.getItem(key);if(!legacy)continue;
      try{
        const parsed=JSON.parse(legacy),sourceSchema=profileSchemaNumber(parsed);
        let migrated=normalizeProfileData(parsed);
        migrated.profileMeta={...safeObject(migrated.profileMeta),lastAppVersion:APP_VERSION};
        beginMigrationJournal(legacy,null,sourceSchema);
        const result=writeCurrentProfile(migrated,{preservePrevious:false,skipConflictCheck:true});
        finishMigrationJournal();profileRecoverySource='legacy';return result.profile;
      }catch(_e){}
    }
    profileBaseRevision=0;return structuredClone(DEFAULT_PROFILE);
  }

  try{
    const parsed=JSON.parse(raw);
    if(!isPlainObject(parsed))throw new Error('profile is not an object');
    const sourceSchema=profileSchemaNumber(parsed);
    if(sourceSchema>PROFILE_SCHEMA_VERSION)throw futureSchemaError(sourceSchema);
    const expected=localStorage.getItem(PROFILE_CHECKSUM_KEY);
    const sourceChecksum=profileChecksumForSchema(parsed,sourceSchema);
    if(expected&&expected!==sourceChecksum)throw new Error('profile checksum mismatch');
    let p=normalizeProfileData(parsed);

    if(sourceSchema<PROFILE_SCHEMA_VERSION){
      beginMigrationJournal(raw,expected||sourceChecksum,sourceSchema);
      p.profileMeta={...safeObject(p.profileMeta),lastAppVersion:APP_VERSION};
      const migrated=writeCurrentProfile(p,{preservePrevious:true,skipConflictCheck:true});
      p=migrated.profile;finishMigrationJournal();profileRecoverySource='migration';
    }else{
      profileBaseRevision=nonNegativeInt(p.profileMeta?.revision,0);
      repairAtomicEnvelopeExact(p);
      if(!expected)try{localStorage.setItem(PROFILE_CHECKSUM_KEY,profileIntegrityChecksum(p))}catch(_e){}
      if(!localStorage.getItem(LAST_GOOD_PROFILE_KEY))try{localStorage.setItem(LAST_GOOD_PROFILE_KEY,raw);localStorage.setItem(LAST_GOOD_CHECKSUM_KEY,sourceChecksum)}catch(_e){}
    }
    return p;
  }catch(e){
    console.warn('学習データの読み込みに失敗しました。',e);
    profileRecoveryWarning=true;profileRecoveryReason=e?.message||String(e);
    if(e?.code==='FUTURE_PROFILE_SCHEMA'){
      profileRecoverySource='future';profileWriteBlocked=true;return structuredClone(DEFAULT_PROFILE);
    }
    try{localStorage.setItem(CORRUPT_PROFILE_KEY,raw)}catch(_e){}
    const snapshot=localStorage.getItem(LAST_GOOD_PROFILE_KEY);
    if(snapshot){
      try{
        const checked=validRawWithChecksum(snapshot,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null);
        profileRecoverySource='snapshot';
        const result=writeCurrentProfile(checked.profile,{preservePrevious:false,skipConflictCheck:true});
        return result.profile;
      }catch(_e){}
    }
    profileRecoverySource='default';profileRecoveryNeedsIndexedDb=true;profileWriteBlocked=true;profileBaseRevision=0;
    return structuredClone(DEFAULT_PROFILE);
  }
}

function nextBChoice(minutes=20){
  const algoTotal=B_EXERCISES.length;
  const secTotal=SECURITY_SCENARIOS.length;
  const algoDone=B_EXERCISES.filter(x=>(profile.bProgress?.[x.id]||0)>=100).length;
  const secDone=SECURITY_SCENARIOS.filter(x=>(profile.securityBProgress?.[x.id]||0)>=100).length;
  const algoRate=algoDone/Math.max(1,algoTotal);
  const secRate=secDone/Math.max(1,secTotal);

  if(algoDone<algoTotal || secDone<secTotal){
    if(algoRate<=secRate && algoDone<algoTotal){
      const ex=B_EXERCISES.find(x=>(profile.bProgress?.[x.id]||0)<100) || B_EXERCISES[0];
      return {mode:'trace',id:ex?.id,title:ex?.title||'アルゴリズムトレース'};
    }
    const sc=SECURITY_SCENARIOS.find(x=>(profile.securityBProgress?.[x.id]||0)<100) || SECURITY_SCENARIOS[0];
    return {mode:'security',id:sc?.id,title:sc?.title||'セキュリティ演習'};
  }

  // 通常の20分枠に100分の総合実戦を自動割当しない。
  // 基礎演習完了後は20分の複合演習とセキュリティ実戦を交互に回す。
  const compoundRuns=(profile.bCompoundHistory||[]).length;
  const securityRuns=(profile.securityMockHistory||[]).length;
  if(compoundRuns<=securityRuns)return {mode:'compound',id:null,title:'複合問題・3問'};
  return {mode:'securityMock',id:null,title:'セキュリティ ミニ模試'};
}

function nextLessonChoice(){
  const weakOrder=sortedSkills().map(x=>x[0]);
  for(const skill of weakOrder){
    const ids=CORE_A_IDS.filter(id=>LESSONS[id].skill===skill);
    const incomplete=ids.find(id=>(profile.lessonProgress?.[id]||0)<100);
    if(incomplete) return {id:incomplete,skill,title:LESSONS[incomplete].title};
  }
  return {id:null,skill:weakOrder[0]||'基礎理論',title:'科目A教材 130テーマ完了',complete:true};
}

