}

function quickProfileIntegrityState(){
  try{
    const a=currentAtomicProfile();
    if(!a)return {ok:false,label:'初回保存前'};
    const mirror=localStorage.getItem(STORAGE_KEY);
    const expected=localStorage.getItem(PROFILE_CHECKSUM_KEY);
    if(!mirror)return {ok:false,label:'ミラー未作成'};
    const checked=validRawWithChecksum(mirror,expected||null);
    if(profileIntegrityChecksum(checked.profile)!==profileIntegrityChecksum(a.profile))return {ok:false,label:'ミラー差異'};
    return {ok:true,label:'正常'};
  }catch(e){return {ok:false,label:'要確認',error:e};}
}

