function rebuildTodayPlanPreservingDone(){
  const rec=getDailyRecord(),old=snapshotDailyTasks(ensureTodayPlanSnapshot()),fresh=snapshotDailyTasks(buildTodayTasks());
  const done=rec.done||{};
  rec.tasks=fresh.map(t=>{
    const slot=dailyTaskSlot(t);
    if(done[slot]){
      return old.find(x=>dailyTaskSlot(x)===slot)||t;
    }
    return t;
  });
  rec.targetMinutes=rec.tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0);
  rec.planVersion='v98';
  rec.replannedAt=new Date().toISOString();
  persistProfileSilently();
  renderDailyPlan();
  renderAllocation();
}

function recoverInterruptedMigrationIfNeeded(){
  const jr=localStorage.getItem(PROFILE_MIGRATION_JOURNAL_KEY);if(!jr)return false;
  try{
    const atomic=currentAtomicProfile();
    if(atomic&&atomic.sourceSchema===PROFILE_SCHEMA_VERSION){finishMigrationJournal();return false}
  }catch(_e){}
  try{
    const j=JSON.parse(jr);
    if(j?.format==='fequest-migration-v1'&&typeof j.raw==='string'){
      const checked=validRawWithChecksum(j.raw,j.checksum||null);
      if(checked.sourceSchema<=PROFILE_SCHEMA_VERSION){
        localStorage.setItem(STORAGE_KEY,j.raw);
        if(j.checksum)localStorage.setItem(PROFILE_CHECKSUM_KEY,j.checksum);else localStorage.removeItem(PROFILE_CHECKSUM_KEY);
        localStorage.removeItem(PROFILE_ATOMIC_KEY);
      }
    }
  }catch(e){console.warn('Interrupted migration rollback failed',e)}
  finishMigrationJournal();return true;
}

async function recoverLatestIndexedDbCheckpoint(){
  if(typeof indexedDB==='undefined')return false;
  let rows=[];
  try{rows=await recoverySnapshots()}catch(e){return false}
  for(const row of rows){
    try{
      const decoded=decodeBackupPayload(row.payload);
      profileWriteBlocked=false;
      profileRecoveryNeedsIndexedDb=false;
      profile=stampProfileForSave(decoded.profile);
      const result=writeCurrentProfile(profile,{preservePrevious:false,skipConflictCheck:true});
      profile=result.profile;rememberCommittedProfile(profile);
      localStorage.setItem(LAST_GOOD_PROFILE_KEY,result.raw);
      localStorage.setItem(LAST_GOOD_CHECKSUM_KEY,result.checksum);
      profileRecoverySource='indexeddb';
      return true;
    }catch(e){console.warn('Skipped invalid recovery checkpoint',e)}
  }
  return false;
}

async function recoveryCandidates(){
  const items=[];
  const lastRaw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);
  if(lastRaw){
    try{
      const checked=validRawWithChecksum(lastRaw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null);
      items.push({kind:'last-good',id:'last-good',label:'一世代前の正常データ',createdAt:checked.profile.profileMeta?.updatedAt||null,reason:'一世代前',profile:checked.profile,valid:true});
    }catch(e){items.push({kind:'last-good',id:'last-good',label:'一世代前のデータ',createdAt:null,reason:'一世代前',valid:false,error:e?.message||String(e)})}
  }
  if(typeof indexedDB!=='undefined'){
    let rows=[];try{rows=await recoverySnapshots()}catch(e){rows=[]}
    for(const row of rows){
      try{
        const decoded=decodeBackupPayload(row.payload);
        items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt||decoded.exportedAt,reason:row.reason,profile:decoded.profile,valid:true});
      }catch(e){items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt,reason:row.reason,valid:false,error:e?.message||String(e)})}
    }
  }
  return items;
}

async function refreshPwaHealth(){
  const v=document.getElementById('pwaVersionStatus'),net=document.getElementById('pwaNetworkStatus'),disp=document.getElementById('pwaDisplayStatus'),worker=document.getElementById('pwaWorkerStatus'),storage=document.getElementById('pwaStorageStatus'),bar=document.getElementById('pwaStorageBar'),persist=document.getElementById('pwaPersistenceStatus'),persistBtn=document.getElementById('requestPersistentStorage');
