  if(v){const mismatch=serviceWorkerVersion&&serviceWorkerVersion!==APP_VERSION;v.textContent=mismatch?`${APP_VERSION}・更新必要`:pendingUpdateRegistration?.waiting?`${APP_VERSION}・更新あり`:APP_VERSION;v.className=(mismatch||pendingUpdateRegistration?.waiting)?'warn':'good'}
