    worker.textContent=controlled?'準備完了':('serviceWorker'in navigator?'準備中':'非対応');worker.className=controlled?'good':'warn';
  }
  if(schema){
    if(profileRecoverySource==='future'){schema.textContent='更新が必要';schema.className='warn';}
    else{schema.textContent=`v${profile.profileSchemaVersion||PROFILE_SCHEMA_VERSION}`;schema.className=(profile.profileSchemaVersion===PROFILE_SCHEMA_VERSION)?'good':'warn';}
  }
  if(saveState){
    if(profileConflictBlocked){saveState.textContent='別画面を検出・停止';saveState.className='warn';}
    else if(profileWriteBlocked){saveState.textContent='保存停止';saveState.className='warn';}
    else{
      try{const a=currentAtomicProfile();const t=a?JSON.parse(localStorage.getItem(PROFILE_ATOMIC_KEY)).savedAt:null;saveState.textContent=a?`r${a.revision}・${t?new Date(t).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}):'保存済み'}`:'初回保存前';saveState.className=a?'good':'warn';}catch(_e){saveState.textContent='要確認';saveState.className='warn';}
    }
  }
  if(integrity){
    const quick=quickProfileIntegrityState();integrity.textContent=quick.ok?'正常':quick.label;integrity.className=quick.ok?'good':'warn';
  }
  if(exportState){
    const raw=localStorage.getItem(PROFILE_LAST_EXPORT_KEY),at=Date.parse(raw||'');
    if(!Number.isFinite(at)){exportState.textContent='未作成';exportState.className='warn';}
    else{const days=Math.floor((Date.now()-at)/86400000);exportState.textContent=days<=0?'今日':`${days}日前`;exportState.className=days<=14?'good':'warn';}
  }
  if(snapshot){
    const localOk=!!localStorage.getItem(LAST_GOOD_PROFILE_KEY);
    const n=await recoveryCheckpointCount();
