function registerReviewedMiss(item){
  if(!item?.wrong) return;
  const stat=getMockMistakeStat(item.q.id);
  if(!stat._countedAttemptKey) stat._countedAttemptKey={};
  const key=`${lastMockAttempt?.date||''}-${item.position}-${lastMockAttempt?.seconds||0}`;
  if(!stat._countedAttemptKey[key]){
    stat.misses=(stat.misses||0)+1;
    stat._countedAttemptKey[key]=true;
    stat.last=localDateISO(0);
    // keep small to avoid unlimited localStorage growth
    const keys=Object.keys(stat._countedAttemptKey);
    if(keys.length>12) delete stat._countedAttemptKey[keys[0]];
    saveProfile();
  }
}

