async function restoreRecoveryCandidate(kind,id,label='復旧点'){
  if(profileRecoverySource==='future'){showAppNotice('error','先にFE QUESTを更新してください','新しい形式の保存データを古い画面から変更しないよう、復旧操作を停止しています。','更新を確認',()=>checkForAppUpdate(true));return false}
  if(profileWriteBlocked||profileConflictBlocked){showAppNotice('error','この画面からは復元できません','保存が停止しているか、別の画面で新しい学習データがあります。最新状態を読み込んでから復旧センターを開いてください。','最新状態を読み込む',()=>location.reload());return false}
  let candidate;try{candidate=await getRecoveryCandidate(kind,id)}catch(e){showAppNotice('error','復旧点を読み取れませんでした',e?.message||'復旧点の整合性を確認できませんでした。');renderRecoveryCenter();return false}
  const currentText=recoveryMetricsText(profile),candidateText=recoveryMetricsText(candidate);
  if(!confirm(`${label}へ戻しますか？

現在：${currentText}
復元先：${candidateText}

現在の状態は「直前の手動復元前」として1回分退避します。`))return false;
  if(!persistProfileSilently()){showAppNotice('error','復元を開始できません','現在の学習データを正常保存できなかったため、復元を中止しました。');return false}
  if(!acquireProfileWriteLease()){markProfileConflict('別のFE QUEST画面がいま学習データを書き込んでいます');return false}
  try{
    assertNoExternalProfileConflict();
    localStorage.setItem(PRE_MANUAL_RESTORE_PROFILE_KEY,JSON.stringify(makeBackupPayload(profile)));
    try{await Promise.race([writeRecoveryCheckpoint(profile,'pre-manual-restore',true),new Promise(resolve=>setTimeout(()=>resolve(false),1800))])}catch(_e){}
    profile=stampProfileForSave(candidate);
    const result=writeCurrentProfile(profile,{preservePrevious:true});profile=result.profile;rememberCommittedProfile(profile);
    localStorage.removeItem('fequest_bfinal_resume_v1');localStorage.removeItem('fequest_ui_state_v2');
    popToast('選んだ復旧点へ戻しました');setTimeout(()=>location.reload(),500);return true;
  }catch(e){
    restoreCommittedProfileInMemory(true);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT')markProfileConflict();else showAppNotice('error','復元できませんでした','現在のデータは変更していません。保存状態を確認してもう一度お試しください。');
    return false;
  }finally{releaseProfileWriteLease()}
}

async function runStorageSelfTest(){
  const status=document.getElementById('recoveryCenterStatus');if(status){status.textContent='安全性チェックを実行しています…';status.className='recovery-center-status'}
  const tests=[];
  const push=(name,ok,detail='')=>tests.push({name,ok,detail});
  const quick=quickProfileIntegrityState(),currentOk=quick.ok||quick.label==='初回保存前';push('現在データの整合性',currentOk,quick.label);
  try{
    const key=`fequest_probe_${Date.now()}`,value=`ok-${Math.random()}`;localStorage.setItem(key,value);const ok=localStorage.getItem(key)===value;localStorage.removeItem(key);push('ブラウザ内の基本保存',ok,ok?'書込・読込・削除OK':'読込値が一致しません');
  }catch(e){push('ブラウザ内の基本保存',false,e?.name||e?.message||'保存不可')}
  if(typeof indexedDB==='undefined')push('長期復旧領域',false,'IndexedDB非対応');
  else{
    const dbName=`fequest-selftest-${Date.now()}`;
    try{
      const db=await new Promise((resolve,reject)=>{const r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>r.result.createObjectStore('probe');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
      const wrote=await new Promise((resolve,reject)=>{const tx=db.transaction('probe','readwrite'),st=tx.objectStore('probe');st.put('ok','k');tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error)});
      const read=await new Promise((resolve,reject)=>{const tx=db.transaction('probe','readonly'),r=tx.objectStore('probe').get('k');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
      db.close();indexedDB.deleteDatabase(dbName);push('長期復旧領域',wrote&&read==='ok','書込・読込OK');
    }catch(e){try{indexedDB.deleteDatabase(dbName)}catch(_e){}push('長期復旧領域',false,e?.name||e?.message||'利用不可')}
  }
  const swSupported='serviceWorker'in navigator;push('オフライン用データ',!swSupported||!!navigator.serviceWorker.controller,swSupported?(navigator.serviceWorker.controller?'制御中':'まだ準備中'):'この環境では非対応');
  const critical=tests.slice(0,3),passed=critical.filter(x=>x.ok).length;
  const lines=tests.map(x=>`${x.ok?'✓':'×'} ${x.name}${x.detail?`：${x.detail}`:''}`);
  if(status){status.textContent=`安全性チェック ${passed}/${critical.length}：${lines.join(' ／ ')}`;status.className=`recovery-center-status ${passed===critical.length?'good':'warn'}`}
  if(passed===critical.length)popToast('学習データの保存機構は正常です');else showAppNotice('error','保存機構に確認が必要です','復旧センターに安全性チェック結果を表示しました。学習を続ける前に外部バックアップを書き出してください。','データを書き出す',exportLearningData);
  refreshPwaHealth();return tests;
}

