function taperFocusRecommendation(days,status=courseMasteryStatus()){
  const ev=categoryCognitiveEvidence(status.weakest[0]);

  // 残り4〜6日は、教材進捗が90%未満なら未学習を1テーマだけ許容。
  // 3日前以降は新規教材を増やさず、既習内容の穴だけを塞ぐ。
  if(days>=4&&status.lessonDone<117){
    const lesson=nextLessonChoice();
    if(lesson?.id)return {kind:'lesson',icon:'📘',title:'未完了教材を1テーマだけ',desc:`教材 ${status.lessonDone}/130。直前に広げすぎず、今日は「${lesson.title}」だけ進めます。`,button:'教材を開く',lessonId:lesson.id};
  }

  if(Number(status.weakest[1])<70){
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${ev.weakest.level}を補強`,desc:`最低分野 ${Math.round(status.weakest[1])}% 。新規範囲ではなく弱い思考を10問で戻します。`,button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
  }

  // 3日前以降は独立した科目B枠を置かないため、Bが弱い場合はこの枠で短く確認。
  if(days<=3&&status.bTraining<90){
    const b=nextBChoice(10);
    return {kind:'subjectB',icon:'💻',title:'科目Bを短く確認',desc:`科目B学習 ${status.bTraining}% 。長時間実戦ではなく未完了の基礎演習を1つ確認します。`,button:'科目Bを確認',b};
  }

  const chapter=nextReadyUnpassedChapter();
  if(chapter){
    return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を統合確認`,desc:'学習済みの章だけを12問で確認します。未学習範囲を直前に混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
  }

  const x=nextMasterTopicCandidate();
  if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
    return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:`現在「${x.state.label}」。既習テーマの保持だけを整えます。`,button:'テーマ演習',topicId:x.topic.id};
  }

  return {kind:'cognitive',icon:'✅',title:`${status.weakest[0]}・${ev.weakest.level}を維持`,desc:'新しい範囲へ広げず、既習の最弱思考を短く確認します。',button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}

function v143NormalizeSelfCheck(raw){
    const result=v142NormalizeSelfCheck(raw);
    const nodeMinimalDom=globalThis.__FEQUEST_RUNTIME_SMOKE__===true || /node-runtime-smoke/i.test(String(globalThis.navigator?.userAgent||''));
    const uiOnly=new Set([
      'v111 result next-action / details hierarchy missing',
      'v111 Subject B results must expose one primary next action',
      'v112 onboarding primary action missing',
      'v112 install guidance must live in settings/data, not home',
      'v113 BIT先生 dialog semantics missing',
      'v113 closed BIT先生 must be non-interactive',
      'v113 live status semantics missing',
      'v113 main navigation landmark missing',
      'v114 home must put the first actionable card before decorative intro copy',
      'v114 mock design/history progressive disclosure missing',
      'v114 weak-analysis details must be secondary',
      'v114 coverage duplicate summary reduction missing',
      'v110 Subject B mode switchers must be progressive disclosure'
    ]);
    const deferred=[];
    const active=[];
    (result.errors||[]).forEach(msg=>{
      if(nodeMinimalDom && uiOnly.has(String(msg))) deferred.push(String(msg));
      else active.push(String(msg));
    });
    const warnings=[...(result.warnings||[]),...deferred.map(msg=>`browser DOM contract deferred in node smoke: ${msg}`)];
    return {
      ...result,
      ok:active.length===0,
      errors:active,
      warnings,
      uiDeferredWarnings:deferred,
      v143RuntimeMode:nodeMinimalDom?'node-minimal-dom':'browser',
      v143DataContract:{
        optionOutlierCount:optionOutliersAfter.length,
        depthShortCount:depthShortAfter.length,
        judgmentGiveawayCount:judgment.options.filter(x=>String(x).includes('だけ確認する')).length,
        dataErrorCount:active.filter(msg=>!uiOnly.has(msg)).length
      }
    };
  }

